def usage_for(opts: dict | None = None) -> str:
    # clap narrows usage for a few single-option errors; reproduce the common cases.
    return f"Usage: {prog()} [OPTIONS] [ROOT]"


def die_parse(message: str, usage: str | None = None, tip: str | None = None) -> None:
    sys.stderr.write(f"error: {message}\n")
    if tip:
        sys.stderr.write(f"\n  tip: {tip}\n")
    if usage:
        sys.stderr.write(f"\n{usage}\n")
