def missing_value(opt_display: str, possible: str | None = None) -> None:
    sys.stderr.write(f"error: a value is required for '{opt_display}' but none was supplied\n")
    if possible:
        sys.stderr.write(f"  [possible values: {possible}]\n")
    raise SystemExit(2)


def unexpected(arg: str, current_opt_usage: str | None = None) -> None:
    usage = current_opt_usage or usage_for()
    if arg.startswith('-'):
        die_parse(f"unexpected argument '{arg}' found", usage, f"to pass '{arg}' as a value, use '-- {arg}'")
    else:
        die_parse(f"unexpected argument '{arg}' found", usage)


def invalid_value(val: str, opt: str, reason: str | None = None, possible: str | None = None) -> None:
    sys.stderr.write(f"error: invalid value '{val}' for '{opt}'")
    if reason:
        sys.stderr.write(f": {reason}")
    sys.stderr.write("\n")
    if possible:
        sys.stderr.write(f"  [possible values: {possible}]\n")
    raise SystemExit(2)


def parse_u16(val: str, optname: str, placeholder: str) -> int:
    try:
        n = int(val, 10)
    except ValueError:
        invalid_value(val, f"--{optname} <{placeholder}>", "invalid digit found in string")
    if n < 0 or n > 65535:
        invalid_value(val, f"--{optname} <{placeholder}>", f"{n} is not in 0..=65535")
    return n


