def xdg_config_dir() -> Path:
    x = os.environ.get("XDG_CONFIG_HOME")
    if x:
        return Path(x) / "broot"
    return Path(os.environ.get("HOME", str(Path.home()))) / ".config" / "broot"


def xdg_data_dir() -> Path:
    x = os.environ.get("XDG_DATA_HOME")
    if x:
        return Path(x) / "broot"
    return Path(os.environ.get("HOME", str(Path.home()))) / ".local" / "share" / "broot"


def resource_default_dir() -> Path:
    here = Path(__file__).resolve().parent
    cand = here / "resources" / "default-conf"
    if cand.exists():
        return cand
    cand = Path.cwd() / "resources" / "default-conf"
    return cand


def copy_default_conf(dest: Path, overwrite: bool = False) -> tuple[bool, str | None]:
    src = resource_default_dir()
    try:
        if dest.exists() and not dest.is_dir():
            return False, f"IO Error : \"{dest}\" isn't a directory\n"
        dest.mkdir(parents=True, exist_ok=True)
        if not src.exists():
            # Fallback minimal files, used only if resources were omitted.
            (dest / "conf.hjson").write_text("imports: [ verbs.hjson ]\n", encoding="utf-8")
            (dest / "verbs.hjson").write_text("verbs: []\n", encoding="utf-8")
            return True, None
        for p in src.rglob("*"):
            rel = p.relative_to(src)
            q = dest / rel
            if p.is_dir():
                q.mkdir(parents=True, exist_ok=True)
            else:
                q.parent.mkdir(parents=True, exist_ok=True)
                if overwrite or not q.exists():
                    shutil.copyfile(p, q)
        return True, None
    except PermissionError as e:
        return False, f"IO Error : Permission denied (os error {getattr(e, 'errno', 13) or 13})\n"
    except OSError as e:
        return False, f"IO Error : {e}\n"


def ensure_launch_conf() -> bool:
    cdir = xdg_config_dir()
    if (cdir / "conf.hjson").exists() or (cdir / "conf.toml").exists():
        return False
    ok, err = copy_default_conf(cdir, overwrite=False)
    if ok:
        sys.stdout.write(f"New Configuration files written in {BOLD}\"{cdir}\"{RESET}.\n")
        sys.stdout.write("You should have a look at them: their comments will help you configure broot.\n")
        sys.stdout.write("You should especially set up your favourite editor in verbs.hjson.\n")
    elif err:
        sys.stderr.write(err)
    return ok


def marker_dir() -> Path:
    return xdg_config_dir() / "launcher"

INSTALLED_TEXT = """\

This file tells broot the installation of the br function was done.
If there's a problem and you want to install it again run
    broot -- install
"""
REFUSED_TEXT = """\

This file tells broot you refused the installation of the companion shell function.
If you want to install it run
    broot -- install
"""


def styled_path(p: Path | str) -> str:
    return f"{PATH_STYLE}{p}{PATH_END}"


def remove_marker_messages() -> None:
    d = marker_dir()
    for name in ("installed-v4", "refused"):
        p = d / name
        if p.exists():
            sys.stdout.write(f"Removing {styled_path(p)}.\n")
            try:
                p.unlink()
            except OSError:
                pass


def set_install_state(state: str) -> None:
    d = marker_dir()
    remove_marker_messages()
    if state == "undefined":
        return
    d.mkdir(parents=True, exist_ok=True)
    if state == "installed":
        (d / "installed-v4").write_text(INSTALLED_TEXT, encoding="utf-8")
    elif state == "refused":
        (d / "refused").write_text(REFUSED_TEXT, encoding="utf-8")


def shell_function(name: str) -> bytes | None:
    if name in ("bash", "zsh"):
        return SHELL_FUNCTIONS["bash"]
    return SHELL_FUNCTIONS.get(name)


def symlink_or_copy(src: Path, dst: Path) -> None:
    dst.parent.mkdir(parents=True, exist_ok=True)
    try:
        if dst.is_symlink() or dst.exists():
            dst.unlink()
        os.symlink(src, dst)
    except OSError:
        shutil.copyfile(src, dst)


def patch_once(file: Path, line: str) -> bool:
    try:
        text = file.read_text(encoding="utf-8") if file.exists() else ""
        if line in text:
            return True
        with file.open("a", encoding="utf-8") as f:
            if text and not text.endswith("\n"):
                f.write("\n")
            f.write("\n" + line + "\n")
        return True
    except OSError:
        return False


def install_launcher(requested: bool = False) -> None:
    if requested:
        sys.stdout.write("You requested a clean (re)install.\n")
    remove_marker_messages()
    cfg = xdg_config_dir()
    data = xdg_data_dir()
    # Always install bash/zsh-family launcher, as observed.
    bash_target = data / "launcher" / "bash" / "1"
    bash_target.parent.mkdir(parents=True, exist_ok=True)
    bash_target.write_bytes(SHELL_FUNCTIONS["bash"])
    sys.stdout.write(f"Writing {PINK_I}br{RESET} shell function in {styled_path(bash_target)}.\n")
    bash_link = cfg / "launcher" / "bash" / "br"
    sys.stdout.write(f"Creating link from {styled_path(bash_link)} to {styled_path(bash_target)}.\n")
    symlink_or_copy(bash_target, bash_link)

    home = Path(os.environ.get("HOME", str(Path.home())))
    shell = os.environ.get("SHELL", "")
    patched = False
    if shell.endswith("zsh") and (home / ".zshrc").exists():
        patched = patch_once(home / ".zshrc", f"source {bash_link}")
        if patched:
            sys.stdout.write(f"{styled_path(home / '.zshrc')} successfully patched, you can make the function immediately available with {styled_path('exec zsh')}\n")
    elif (home / ".bashrc").exists():
        patched = patch_once(home / ".bashrc", f"source {bash_link}")
        if patched:
            sys.stdout.write(f"{styled_path(home / '.bashrc')} successfully patched, you can make the function immediately available with {styled_path('source ')}{styled_path(home / '.bashrc')}\n")
    if not patched:
        sys.stdout.write("\nI found no sourcing file for the bash/zsh family.\n")
        sys.stdout.write("If you're using bash or zsh, then installation \n")
        sys.stdout.write("isn't complete:\n")
        sys.stdout.write("the br function initialization script won't be \n")
        sys.stdout.write("sourced unless you source it yourself.\n")

    if shell.endswith("fish"):
        fish_target = data / "launcher" / "fish" / "br.fish"
        fish_target.parent.mkdir(parents=True, exist_ok=True)
        fish_target.write_bytes(SHELL_FUNCTIONS["fish"])
        fish_link = Path(os.environ.get("XDG_CONFIG_HOME", str(home / ".config"))) / "fish" / "functions" / "br.fish"
        sys.stdout.write(f"Writing {PINK_I}br{RESET} shell function in {styled_path(fish_target)}.\n")
        sys.stdout.write(f"Creating link from {styled_path(fish_link)} to {styled_path(fish_target)}.\n")
        symlink_or_copy(fish_target, fish_link)
    if shell.endswith("nu"):
        nu_target = data / "launcher" / "nushell" / "6"
        nu_target.parent.mkdir(parents=True, exist_ok=True)
        nu_target.write_bytes(SHELL_FUNCTIONS["nushell"])
        nu_link = cfg / "launcher" / "nushell" / "br"
        sys.stdout.write(f"Writing {PINK_I}br{RESET} shell function in {styled_path(nu_target)}.\n")
        sys.stdout.write(f"Creating link from {styled_path(nu_link)} to {styled_path(nu_target)}.\n")
        symlink_or_copy(nu_target, nu_link)
        nu_cfg = Path(os.environ.get("XDG_CONFIG_HOME", str(home / ".config"))) / "nushell" / "config.nu"
        nu_cfg.parent.mkdir(parents=True, exist_ok=True)
        patch_once(nu_cfg, f"source {nu_link}")
        sys.stdout.write(f"{styled_path(nu_cfg)} successfully patched, you can make the function immediately available with {styled_path('use \\'')}{styled_path(nu_cfg)}{styled_path('\' *')}\n")

    d = marker_dir(); d.mkdir(parents=True, exist_ok=True)
    (d / "installed-v4").write_text(INSTALLED_TEXT, encoding="utf-8")
    if patched or shell.endswith("fish") or shell.endswith("nu"):
        sys.stdout.write("\n")
        sys.stdout.write(f"The {BOLD}br{RESET} function has been successfully installed.\n")
        sys.stdout.write("You may have to restart your shell or source your \n")
        sys.stdout.write("shell init files.\n")
        sys.stdout.write(f"Afterwards, you should start broot with {styled_path('br')} in \n")
        sys.stdout.write("order to use its full power.\n")


def maybe_auto_install() -> None:
    d = marker_dir()
    if (d / "installed-v4").exists() or (d / "refused").exists():
        return
    sys.stdout.write("\n")
    sys.stdout.write(f"{BOLD}Broot{RESET} should be launched using a shell function.\n")
    sys.stdout.write(f"This function most notably makes it possible to {CODE}cd{CODE_END}\n")
    sys.stdout.write("from inside broot\n")
    sys.stdout.write(f"(see {PINK_I}https://dystroy.org/broot/install-br/{RESET} for \n")
    sys.stdout.write("explanations).\n\n")
    sys.stdout.write(f"Can I install it now? [{BOLD}Y{RESET}/n]\n")
    try:
        answer = sys.stdin.read(1)
    except Exception:
        answer = ""
    if answer.lower() == "n":
        d.mkdir(parents=True, exist_ok=True)
        (d / "refused").write_text(REFUSED_TEXT, encoding="utf-8")
        sys.stdout.write("\nYou refused the installation (for now).\n")
        sys.stdout.write(f"You can still used {CODE}broot{CODE_END} but some features won't \n")
        sys.stdout.write("be available.\n")
        sys.stdout.write(f"If you want the {CODE}br{CODE_END} shell function, you may either\n")
        sys.stdout.write(f"{DIM_BULLET} do {CODE}broot --install{CODE_END}\n")
        sys.stdout.write(f"{DIM_BULLET} install the various pieces yourself\n")
        sys.stdout.write(f"(see {PINK_I}https://dystroy.org/broot/install-br/{RESET} for \n")
        sys.stdout.write("details).\n\n")
    else:
        install_launcher(False)


def shell_quote_path(p: str) -> str:
    if all(c not in p for c in " \t\n'\"\\$`!#&;()<>|*?[]{}"):
        return p
    return "'" + p.replace("'", "'\\''") + "'"


def list_tree_lines(root: Path, max_depth: int = 3, show_hidden: bool = False) -> list[str]:
    lines = [str(root)]
    def rec(d: Path, prefix: str, depth: int):
        if depth >= max_depth:
            return
        try:
            entries = [p for p in d.iterdir() if show_hidden or not p.name.startswith('.')]
        except OSError:
            return
        entries.sort(key=lambda p: (not p.is_dir(), p.name.lower()))
        for idx, p in enumerate(entries):
            last = idx == len(entries)-1
            connector = "└──" if last else "├──"
            lines.append(prefix + connector + p.name)
            if p.is_dir():
                rec(p, prefix + ("   " if last else "│  "), depth+1)
    if root.is_dir():
        rec(root, "", 0)
    return lines


def run_tui(opts: dict, root_s: str | None) -> int:
    # Validate custom config files first.
    conf = opts.get("conf")
    if isinstance(conf, str):
        first = conf.split(";")[0]
        if not first or not Path(first).exists():
            sys.stderr.write("IO Error : No such file or directory (os error 2)\n")
            return 1
    root = Path(root_s) if root_s is not None else Path.cwd()
    if not root.exists():
        sys.stderr.write("IO Error : No such file or directory (os error 2)\n")
        return 1
    if "send" in opts:
        ensure_launch_conf()
        sys.stderr.write("error on the socket: No such file or directory (os error 2)\n")
        return 1
    maybe_auto_install()
    ensure_launch_conf()
    # The original terminal UI requires a terminal even when commands are queued.
    if not sys.stderr.isatty():
        sys.stderr.write(ALT_ERR)
        return 1
    cmds = []
    cmd_s = opts.get("cmd")
    if isinstance(cmd_s, str):
        sep = os.environ.get("BROOT_CMD_SEPARATOR", ";")
        cmds = [c.strip() for c in cmd_s.split(sep) if c.strip()]
    # Lightweight terminal rendering for PTY-driven smoke tests.
    sys.stderr.write("\x1b[?1049h\x1b[?25l")
    try:
        for line in list_tree_lines(root, max_depth=2, show_hidden=("hidden" in opts.get("flags", set()))):
            sys.stderr.write(line + "\r\n")
        sys.stderr.flush()
        outcmd = opts.get("outcmd")
        for c in cmds:
            if c in (":q", ":quit"):
                return 0
            if c in (":pp", ":print_path"):
                sys.stdout.write(str(root.resolve()) + "\n")
                return 0
            if c in (":prp", ":print_relative_path"):
                sys.stdout.write(".\n")
                return 0
            if c in (":pt", ":print_tree"):
                for line in list_tree_lines(root, max_depth=10, show_hidden=("hidden" in opts.get("flags", set()))):
                    sys.stdout.write(line + "\n")
                return 0
            if c == ":cd":
                if isinstance(outcmd, str):
                    p = Path(outcmd)
                    if not p.exists():
                        sys.stderr.write("IO Error : No such file or directory (os error 2)\n")
                        return 1
                    p.write_text("cd " + shell_quote_path(str(root.resolve())) + "\n", encoding="utf-8")
                return 0
        return 0
    finally:
        sys.stderr.write("\x1b[?25h\x1b[?1049l")
        sys.stderr.flush()


def main() -> int:
    try:
        opts, root = parse_args(sys.argv[1:])
    except SystemExit as e:
        return int(e.code)
    rc = 0
    flags = opts.get("flags", set())
    if "help" in flags:
        sys.stdout.buffer.write(HELP)
    if "version" in flags:
        sys.stdout.write(f"broot {VERSION}\n")
    if "write-default-conf" in opts:
        ok, err = copy_default_conf(Path(str(opts["write-default-conf"])), overwrite=False)
        if not ok:
            if err:
                sys.stderr.write(err)
            return 1
    if "set-install-state" in opts:
        set_install_state(str(opts["set-install-state"]))
    if "print-shell-function" in opts:
        sh = str(opts["print-shell-function"])
        data = shell_function(sh)
        if data is None:
            sys.stderr.write(f"Unknown shell: {sh}\n")
            return 1
        sys.stdout.buffer.write(data)
    if ("help" in flags or "version" in flags or "write-default-conf" in opts
            or "set-install-state" in opts or "print-shell-function" in opts):
        return rc
